);

CREATE TABLE COURSES (
    STUDENT VARCHAR(255),
    CLASS VARCHAR(255),
    PRIMARY KEY (STUDENT)
);

counterexample:
-- No INSERT statements can create a counterexample without violating the PRIMARY KEY constraint on STUDENT.
-- However, to demonstrate that both queries return the same result for any valid data, here is a minimal example:
INSERT INTO COURSES (STUDENT, CLASS) VALUES ('S1', 'Math');
INSERT INTO COURSES (STUDENT, CLASS) VALUES ('S2', 'Math');
INSERT INTO COURSES (STUDENT, CLASS) VALUES ('S3', 'Math');
INSERT INTO COURSES (STUDENT, CLASS) VALUES ('S4', 'Math');
INSERT INTO COURSES (STUDENT, CLASS) VALUES ('S5', 'Math');
-- With this data, both Q1 and Q2 will output 'Math' since COUNT(*) and COUNT(DISTINCT STUDENT) are both 5. No difference occurs.

